CREATE TABLE P360_PRODUCTS (ID BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, VERSION BIGINT, NAME VARCHAR(80) NOT NULL, CATEGORY VARCHAR(80) NOT NULL, PRICE DECIMAL(12,2) NOT NULL, STORE_ID BIGINT NOT NULL, STOCK INTEGER NOT NULL CHECK(STOCK >= 0), ACTIVE BOOLEAN NOT NULL);
CREATE INDEX IDX_PRODUCT_STORE ON P360_PRODUCTS(STORE_ID);
CREATE TABLE P360_RESERVATIONS (ID VARCHAR(80) PRIMARY KEY, DIGEST VARCHAR(64) NOT NULL, PAYLOAD CLOB NOT NULL, RELEASED BOOLEAN NOT NULL);
